27: // TiffStdOut.hpp
28: // ==============
29: // This file contains the standard output functionality for TIFF images. This
30: // is intended to provide easy output of TIFF image metadata and structure
31: // information to standard output for debugging and exploration.
32: 
33: #pragma once
34: 
35: #include "TiffImage.hpp"
36: 
37: #include <string>
38: #include <iostream>
39: #include <iomanip>
40: 
41: namespace TiffCraft {
42:   inline std::string toString(Tag tag)
43:   {
44:     switch (tag) {
45:       case TiffCraft::Tag::Null: return "Null";
46:       case TiffCraft::Tag::NewSubfileType: return "NewSubfileType";
47:       case TiffCraft::Tag::SubfileType: return "SubfileType";
48:       case TiffCraft::Tag::ImageWidth: return "ImageWidth";
49:       case TiffCraft::Tag::ImageLength: return "ImageLength";
50:       case TiffCraft::Tag::BitsPerSample: return "BitsPerSample";
51:       case TiffCraft::Tag::Compression: return "Compression";
52:       case TiffCraft::Tag::PhotometricInterpretation: return "PhotometricInterpretation";
53:       case TiffCraft::Tag::Thresholding: return "Thresholding";
54:       case TiffCraft::Tag::FillOrder: return "FillOrder";
55:       case TiffCraft::Tag::DocumentName: return "DocumentName";
56:       case TiffCraft::Tag::ImageDescription: return "ImageDescription";
57:       case TiffCraft::Tag::Make: return "Make";
58:       case TiffCraft::Tag::Model: return "Model";
59:       case TiffCraft::Tag::StripOffsets: return "StripOffsets";
60:       case TiffCraft::Tag::Orientation: return "Orientation";
61:       case TiffCraft::Tag::SamplesPerPixel: return "SamplesPerPixel";
62:       case TiffCraft::Tag::RowsPerStrip: return "RowsPerStrip";
63:       case TiffCraft::Tag::StripByteCounts: return "StripByteCounts";
64:       case TiffCraft::Tag::MinSampleValue: return "MinSampleValue";
65:       case TiffCraft::Tag::MaxSampleValue: return "MaxSampleValue";
66:       case TiffCraft::Tag::XResolution: return "XResolution";
67:       case TiffCraft::Tag::YResolution: return "YResolution";
68:       case TiffCraft::Tag::PlanarConfiguration: return "PlanarConfiguration";
69:       case TiffCraft::Tag::ResolutionUnit: return "ResolutionUnit";
70:       case TiffCraft::Tag::PageName: return "PageName";
71:       case TiffCraft::Tag::Software: return "Software";
72:       case TiffCraft::Tag::DateTime: return "DateTime";
73:       case TiffCraft::Tag::Artist: return "Artist";
74:       case TiffCraft::Tag::ColorMap: return "ColorMap";
75:       case TiffCraft::Tag::HalftoneHints: return "HalftoneHints";
76:       case TiffCraft::Tag::TileWidth: return "TileWidth";
77:       case TiffCraft::Tag::TileLength: return "TileLength";
78:       case TiffCraft::Tag::TileOffsets: return "TileOffsets";
79:       case TiffCraft::Tag::TileByteCounts: return "TileByteCounts";
80:       case TiffCraft::Tag::SampleFormat: return "SampleFormat";
81:       default: /* unknown tag */ break;
82:     }
83:     char buf[8] = "0x0000";
84:     std::snprintf(buf, sizeof(buf), "0x%04X", static_cast<uint16_t>(tag));
85:     return buf;
86:   }
87: 
88:   inline std::string_view toString(Type type) {
89:     switch (type) {
90:       case TiffCraft::Type::BYTE:      return "BYTE";
91:       case TiffCraft::Type::ASCII:     return "ASCII";
92:       case TiffCraft::Type::SHORT:     return "SHORT";
93:       case TiffCraft::Type::LONG:      return "LONG";
94:       case TiffCraft::Type::RATIONAL:  return "RATIONAL";
95:       case TiffCraft::Type::SBYTE:     return "SBYTE";
96:       case TiffCraft::Type::UNDEFINED: return "UNDEFINED";
97:       case TiffCraft::Type::SSHORT:    return "SSHORT";
98:       case TiffCraft::Type::SLONG:     return "SLONG";
99:       case TiffCraft::Type::SRATIONAL: return "SRATIONAL";
100:       case TiffCraft::Type::FLOAT:     return "FLOAT";
101:       case TiffCraft::Type::DOUBLE:    return "DOUBLE";
102:       default:                         return "!UNKNOWN";
103:     }
104:   }
105: }
