78: namespace std {
79:   template <typename T>
80:   T byteswap(T value) {
81:     static_assert(std::is_trivially_copyable_v<T>, "Type must be trivially copyable");
82:     T result;
83:     std::reverse_copy(reinterpret_cast<const char*>(&value),
84:                       reinterpret_cast<const char*>(&value) + sizeof(T),
85:                       reinterpret_cast<char*>(&result));
86:     return result;
87:   }
88: }
