149:   template <typename T>
150:   struct RationalT {
151:     T numerator;
152:     T denominator;
153:   };
154: 
155:   template <typename>
156:   struct is_rational : std::false_type {};
157: 
158:   template <typename U>
159:   struct is_rational<RationalT<U>> : std::true_type {};
160: 
161:   template <typename T>
162:   constexpr bool is_rational_v = is_rational<T>::value;
163: 
164:   using Rational = RationalT<uint32_t>;
165:   static_assert(sizeof(Rational) == 8, "Rational must be 8 bytes");
166: 
167:   using SRational = RationalT<int32_t>;
168:   static_assert(sizeof(SRational) == 8, "SRational must be 8 bytes");
169: 
170:   // TIFF data types
171:   // ===============
172:   // 1 = BYTE 8-bit unsigned integer.
173:   // 2 = ASCII 8-bit byte that contains a 7-bit ASCII code; the last byte
174:   //     must be NUL (binary zero).
175:   // 3 = SHORT 16-bit (2-byte) unsigned integer.
176:   // 4 = LONG 32-bit (4-byte) unsigned integer.
177:   // 5 = RATIONAL Two LONGs: the first represents the numerator of a
178:   //     fraction; the second, the denominator.
179:   // 6 = SBYTE An 8-bit signed (twos-complement) integer.
180:   // 7 = UNDEFINED An 8-bit byte that may contain anything, depending on
181:   //     the definition of the field.
182:   // 8 = SSHORT A 16-bit (2-byte) signed (twos-complement) integer.
183:   // 9 = SLONG A 32-bit (4-byte) signed (twos-complement) integer.
184:   // 10 = SRATIONAL Two SLONG’s: the first represents the numerator of a
185:   //      fraction, the second the denominator.
186:   // 11 = FLOAT Single precision (4-byte) IEEE format.
187:   // 12 = DOUBLE Double precision (8-byte) IEEE format
188:   enum class Type : uint16_t {
189:     BYTE = 1,
190:     ASCII = 2,
191:     SHORT = 3,
192:     LONG = 4,
193:     RATIONAL = 5,
194:     SBYTE = 6,
195:     UNDEFINED = 7,
196:     SSHORT = 8,
197:     SLONG = 9,
198:     SRATIONAL = 10,
199:     FLOAT = 11,
200:     DOUBLE = 12
201:   };
202: 
203:   template <Type type> struct TypeTraits;
204:   template <> struct TypeTraits<Type::BYTE> { using type = uint8_t; };
205:   template <> struct TypeTraits<Type::ASCII> { using type = char; };
206:   template <> struct TypeTraits<Type::SHORT> { using type = uint16_t; };
207:   template <> struct TypeTraits<Type::LONG> { using type = uint32_t; };
208:   template <> struct TypeTraits<Type::RATIONAL> { using type = Rational; };
209:   template <> struct TypeTraits<Type::SBYTE> { using type = int8_t; };
210:   template <> struct TypeTraits<Type::UNDEFINED> { using type = std::byte; };
211:   template <> struct TypeTraits<Type::SSHORT> { using type = int16_t; };
212:   template <> struct TypeTraits<Type::SLONG> { using type = int32_t; };
213:   template <> struct TypeTraits<Type::SRATIONAL> { using type = SRational; };
214:   template <> struct TypeTraits<Type::FLOAT> { using type = float; };
215:   template <> struct TypeTraits<Type::DOUBLE> { using type = double; };
216: 
217:   template <Type type> using TypeTraits_t = typename TypeTraits<type>::type;
218: 
219:   template <typename F>
220:   decltype(auto) dispatchType(Type type, F&& f) {
221:     switch (type) {
222:       case Type::BYTE:      return f.template operator()<Type::BYTE>();
223:       case Type::ASCII:     return f.template operator()<Type::ASCII>();
224:       case Type::SHORT:     return f.template operator()<Type::SHORT>();
225:       case Type::LONG:      return f.template operator()<Type::LONG>();
226:       case Type::RATIONAL:  return f.template operator()<Type::RATIONAL>();
227:       case Type::SBYTE:     return f.template operator()<Type::SBYTE>();
228:       case Type::UNDEFINED: return f.template operator()<Type::UNDEFINED>();
229:       case Type::SSHORT:    return f.template operator()<Type::SSHORT>();
230:       case Type::SLONG:     return f.template operator()<Type::SLONG>();
231:       case Type::SRATIONAL: return f.template operator()<Type::SRATIONAL>();
232:       case Type::FLOAT:     return f.template operator()<Type::FLOAT>();
233:       case Type::DOUBLE:    return f.template operator()<Type::DOUBLE>();
234:       default:
235:         throw std::runtime_error("Unknown TIFF entry type");
236:     }
237:   }
238: 
239:   inline uint32_t typeBytes(Type type) {
240:     return dispatchType(type, []<Type type>() -> uint32_t {
241:       return sizeof(TypeTraits_t<type>);
242:     });
243:   }
244: 
245:   template <typename SrcType, typename DstType>
246:   void copyVector(const std::byte* src, size_t count, std::vector<DstType>& dest) {
247:     if constexpr (std::is_convertible_v<SrcType, DstType>) {
248:       if (sizeof(DstType) < sizeof(SrcType)) {
249:         throw std::runtime_error("Destination type size is smaller than source type size");
250:       }
251:       dest.resize(count);
252:       const SrcType* srcPtr = reinterpret_cast<const SrcType*>(src);
253:       for (size_t i = 0; i < count; ++i) {
254:         dest[i] = static_cast<DstType>(srcPtr[i]);
255:       }
256:     } else {
257:       throw std::runtime_error("Source type is not convertible to destination type");
258:     }
259:   }
260: 
261:   template <typename DstType>
262:   void copyVector(Type type, const std::byte* src, size_t count, std::vector<DstType>& dest) {
263:     dispatchType(type, [&]<Type type>() {
264:       copyVector<TypeTraits_t<type>, DstType>(src, count, dest);
265:     });
266:   }
