313:   // Helper functions for working with streams
314:   template <typename T>
315:   std::istream& readValue(std::istream& stream, T& value, bool mustSwap = false) {
316:     if (!stream) {
317:       throw std::runtime_error("Stream is not valid for reading");
318:     }
319:     stream.read(reinterpret_cast<char*>(&value), sizeof(value));
320:     if (mustSwap) {
321:       value = swap(value);
322:     }
323:     return stream;
324:   }
325: 
326:   template <typename T>
327:   T readValue(std::istream& stream, bool mustSwap = false) {
328:     T value;
329:     readValue(stream, value, mustSwap);
330:     return value;
331:   }
332: 
333:   std::istream& readAt(
334:     std::istream& stream, std::streampos pos,
335:     std::byte* buffer, std::size_t size) {
336:     if (!stream) {
337:       throw std::runtime_error("Stream is not valid for reading");
338:     }
339:     struct SeekGuard {
340:       std::istream& stream;
341:       std::streampos oldPos;
342:       SeekGuard(std::istream& s, std::streampos p) : stream(s), oldPos(s.tellg()) {
343:         stream.seekg(p);
344:       }
345:       ~SeekGuard() {
346:         stream.seekg(oldPos);
347:       }
348:     } seekGuard(stream, pos);
349:     if (!stream) {
350:       throw std::runtime_error("Failed to seek to position in stream");
351:     }
352:     stream.read(reinterpret_cast<char*>(buffer), size);
353:     return stream;
354:   }
355: 
356:   template <typename T>
357:   std::ostream& writeValue(std::ostream& stream, T value, bool mustSwap = false) {
358:     if (!stream) {
359:       throw std::runtime_error("Stream is not valid for writing");
360:     }
361:     if (mustSwap) {
362:       value = swap(value);
363:     }
364:     stream.write(reinterpret_cast<const char*>(&value), sizeof(value));
365:     return stream;
366:   }
367: 
368:   std::ostream& writeAt(
369:     std::ostream& stream, std::streampos pos,
370:     const std::byte* buffer, std::size_t size) {
371:     if (!stream) {
372:       throw std::runtime_error("Stream is not valid for writing");
373:     }
374:     struct SeekGuard {
375:       std::ostream& stream;
376:       std::streampos oldPos;
377:       SeekGuard(std::ostream& s, std::streampos p) : stream(s), oldPos(s.tellp()) {
378:         // try to seek to the specified position
379:         stream.seekp(p);
380:         if (stream.fail()) {
381:           // if seeking fails, we check if we tried to seek beyond the end of
382:           // the stream and if so, we pad the stream with zeros until we reach
383:           // the desired position
384:           stream.clear(); // Clear any error flags
385:           stream.seekp(0, std::ios_base::end);
386:           while (stream && stream.tellp() < p) {
387:             stream.put(0); // Pad with zeros if necessary
388:           }
389:           assert(stream.tellp() == p && "SeekGuard did not reach the desired position");
390:         }
391:       }
392:       ~SeekGuard() {
393:         stream.seekp(oldPos);
394:       }
395:     } seekGuard(stream, pos);
396:     if (!stream || stream.tellp() != pos) {
397:       throw std::runtime_error("Failed to seek to position in stream");
398:     }
399:     stream.write(reinterpret_cast<const char*>(buffer), size);
400:     return stream;
401:   }
